const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const greatLakes = ee.FeatureCollection('WWF/HydroSHEDS/v1/Basins/hybas_4')
    .filter(ee.Filter.inList('HYBAS_ID', [4100232720, 4100232710, 4100232700, 4100232690, 4100232680]));

  const date = '2018-02-14';
  const startDate = ee.Date(date);
  const endDate = startDate.advance(1, 'day');

  // 2. Data Acquisition - Use MODIS Terra for afternoon coverage
  // MOD09GA has surface reflectance at 500m with quality flags
  const modisCol = ee.ImageCollection('MODIS/006/MOD09GA')
    .filterDate(startDate, endDate)
    .filterBounds(greatLakes);

  if (modisCol.size().getInfo() === 0) {
    console.log("No MODIS images found for Feb 14, 2018.");
    console.log("<answer>C1</answer>");
    return;
  }

  // Process MODIS data for ice detection
  const modisImg = modisCol.first();

  // Use Band 6 (1.6μm) for ice detection - snow/ice has low reflectance in SWIR
  const swir = modisImg.select('sur_refl_b06').multiply(0.0001); // Scale factor
  const blue = modisImg.select('sur_refl_b03').multiply(0.0001);

  // Simple ice/snow detection: low SWIR reflectance
  const iceMask = swir.lt(0.2); // Threshold for potential ice

  // Quality mask from state_1km band
  const qa = modisImg.select('state_1km');
  const cloudMask = qa.bitwiseAnd(1 << 10).eq(0); // Clear if cloud bit not set

  // Combine masks
  const validMask = iceMask.and(cloudMask);

  // Process each lake
  const lakeNames = ['Superior', 'Michigan', 'Huron', 'Erie', 'Ontario'];
  const lakeGeoms = greatLakes.toList(greatLakes.size()).getInfo();

  let results = {};
  let maxIceLake = '';
  let maxIcePercent = -1;

  for (let i = 0; i < lakeGeoms.length; i++) {
    const lakeGeom = ee.Feature(lakeGeoms[i]).geometry();

    // Count total valid water pixels (using blue band > 0 as water proxy)
    const waterMask = blue.gt(0.01);
    const waterCount = waterMask.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: lakeGeom,
      scale: 1000,
      maxPixels: 1e9
    }).get('sur_refl_b03').getInfo();

    if (waterCount === 0) {
      console.log(`${lakeNames[i]}: No valid water pixels`);
      results[lakeNames[i]] = 0;
      continue;
    }

    // Count ice pixels
    const iceCount = validMask.updateMask(waterMask).reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: lakeGeom,
      scale: 1000,
      maxPixels: 1e9
    }).get('sur_refl_b06').getInfo();

    const icePercent = (iceCount / waterCount) * 100;
    results[lakeNames[i]] = icePercent;

    console.log(`${lakeNames[i]}: ${icePercent.toFixed(1)}% ice (${iceCount}/${waterCount} pixels)`);

    if (icePercent > maxIcePercent) {
      maxIcePercent = icePercent;
      maxIceLake = lakeNames[i];
    }
  }

  // 5. Validation & Final Answer
  if (Object.keys(results).length === 0) {
    console.log("No valid pixels in any lake.");
    console.log("<answer>C2</answer>");
    return;
  }

  // Check if Erie has the highest percentage
  const eriePercent = results['Erie'] || 0;
  const otherMax = Math.max(...Object.entries(results)
    .filter(([name]) => name !== 'Erie')
    .map(([_, val]) => val));

  console.log(`Erie: ${eriePercent.toFixed(1)}%, Other max: ${otherMax.toFixed(1)}%`);

  if (eriePercent > otherMax + 0.1) { // Small buffer for floating point
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
```

**Thinking process:**

1. **Search strategy**: 
   - Use MODIS Terra (MOD09GA) which has afternoon overpass (~10:30 AM local time)
   - Great Lakes basin boundaries from HydroSHEDS dataset
   - Single date: February 14, 2018

2. **Masking strategy**:
   - Use SWIR band (1.6μm) with threshold <0.2 for ice detection (ice has low SWIR reflectance)
   - Cloud masking using MODIS quality flags
   - Water mask using blue band > 0.01 to focus on lake areas

3. **Validation logic**:
   - Count ice pixels vs total water pixels for each lake
   - Calculate percentage ice coverage
   - Compare Erie's percentage to maximum of other lakes
   - Use small buffer (0.1%) to account for floating point precision

**Key decisions**:
- MODIS at 500m resolution provides adequate coverage for large lakes
- Simple SWIR threshold works for ice vs open water discrimination
- Calculate ice percentage rather than absolute area due to different lake sizes
- If Erie has highest percentage → Yes (A), otherwise → No (B)

